  border-color: #0A84FF;
  outline: 0;
  background-color: rgba(28, 28, 30, 0.95);
  -webkit-box-shadow: inset 0 1px 2px rgba(0,0,0,.3), 0 0 0 3px rgba(10, 132, 255, 0.25);
  box-shadow: inset 0 1px 2px rgba(0,0,0,.3), 0 0 0 3px rgba(10, 132, 255, 0.25);
}
.form-control::-moz-placeholder { color: #636366; opacity: 1; }
.form-control:-ms-input-placeholder { color: #636366; }
.form-control::-webkit-input-placeholder { color: #636366; }
.form-control[disabled],
.form-control[readonly],
fieldset[disabled] .form-control {
  background-color: #1C1C1E;
  opacity: 0.6;
  cursor: not-allowed;
}
textarea.form-control { height: auto; }

.form-group { margin-bottom: 15px; }
label {
  display: inline-block;
  max-width: 100%;
  margin-bottom: 5px;
  font-weight: 500;
  color: #EBEBF5;
}

.has-success .form-control {
  border-color: #30D158;
  box-shadow: inset 0 1px 2px rgba(0,0,0,.3), 0 0 0 2px rgba(48, 209, 88, 0.2);
}
.has-success .form-control:focus {
  border-color: #30D158;
  box-shadow: inset 0 1px 2px rgba(0,0,0,.3), 0 0 0 3px rgba(48, 209, 88, 0.3);
}
.has-warning .form-control {
  border-color: #FF9F0A;
  box-shadow: inset 0 1px 2px rgba(0,0,0,.3), 0 0 0 2px rgba(255, 159, 10, 0.2);
}
.has-error .form-control {
  border-color: #FF453A;
  box-shadow: inset 0 1px 2px rgba(0,0,0,.3), 0 0 0 2px rgba(255, 69, 58, 0.2);
}

/* ============================================================
   PANELS / CARDS - Dark Glass
   ============================================================ */

.panel,
.r-grid > .panel,
.modal-content,
.dropdown-menu,
.popover,
.navbar,
.navbar-default,
.navbar-inverse,
.well,
.thumbnail,
.list-group,
.r-box-left,
.r-box-right,
.filterPanelContainer .panel,
[data-dashboard] [data-dashtype] > .panel,
.rnr-details-popup,
.bs-popup,
.panel.form-section {
  background: rgba(28, 28, 30, 0.72) !important;
  -webkit-backdrop-filter: saturate(180%) blur(24px);
  backdrop-filter: saturate(180%) blur(24px);
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  box-shadow:
    0 4px 24px rgba(0, 0, 0, 0.4),
    0 1px 2px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.06) !important;
  border-radius: 14px !important;
  color: #F5F5F7;
}

.modal-content,
.dropdown-menu,
.popover,
.rnr-details-popup {
  background: rgba(36, 36, 38, 0.88) !important;
  -webkit-backdrop-filter: saturate(200%) blur(32px);
  backdrop-filter: saturate(200%) blur(32px);
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 16px !important;
  box-shadow:
    0 16px 48px rgba(0, 0, 0, 0.55),
    0 4px 16px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.08) !important;
}

.panel > .panel-heading,
.panel > .panel-footer,
.r-grid > .panel > .panel-heading,
.r-grid > .panel > .panel-footer {
  background: rgba(44, 44, 46, 0.55) !important;
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border-color: rgba(255, 255, 255, 0.06) !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06) !important;
  color: #F5F5F7 !important;
}
.panel > .panel-footer {
  border-top: 1px solid rgba(255, 255, 255, 0.06) !important;
  border-bottom: none !important;
}

.panel-title { color: #F5F5F7; }

/* ============================================================
   NAVBAR / SIDEBAR
   ============================================================ */

.navbar,
.navbar-default,
.navbar-inverse,
[data-location="supertop"] {
  background: rgba(22, 22, 24, 0.85) !important;
  -webkit-backdrop-filter: saturate(180%) blur(28px);
  backdrop-filter: saturate(180%) blur(28px);
  border: none !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06) !important;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.04) inset,
              0 4px 24px rgba(0, 0, 0, 0.35) !important;
}

.r-left,
.r-vbar-page .r-left {
  background: rgba(22, 22, 24, 0.75) !important;
  -webkit-backdrop-filter: saturate(180%) blur(28px);
  backdrop-filter: saturate(180%) blur(28px);
  border-right: 1px solid rgba(255, 255, 255, 0.06) !important;
}

.navbar-default .navbar-nav > li > a,
.navbar-inverse .navbar-nav > li > a {
  color: #EBEBF5;
}
.navbar-default .navbar-nav > li > a:hover,
.navbar-default .navbar-nav > li > a:focus,
.navbar-inverse .navbar-nav > li > a:hover,
.navbar-inverse .navbar-nav > li > a:focus {
  color: #fff;
  background: rgba(10, 132, 255, 0.15);
}

/* ============================================================
   TABLES
   ============================================================ */

.table {
  background: transparent;
  color: #F5F5F7;
}
.table > thead > tr > th,
.table > tbody > tr > th,
.table > tfoot > tr > th,
.table > thead > tr > td,
.table > tbody > tr > td,
.table > tfoot > tr > td {
  padding: 10px 12px;
  line-height: 1.42857143;
  vertical-align: top;
  border-top: 1px solid #3A3A3C;
}
.table > thead > tr > th {
  vertical-align: bottom;
  border-bottom: 2px solid #3A3A3C;
  color: #98989D;
  font-weight: 600;
}
.table-striped > tbody > tr:nth-of-type(odd) {
  background-color: rgba(255, 255, 255, 0.03) !important;
}
.table-hover > tbody > tr:hover {
  background-color: rgba(10, 132, 255, 0.1) !important;
}
.table-bordered {
  border: 1px solid #3A3A3C;
}
.table-bordered > thead > tr > th,
.table-bordered > tbody > tr > th,
.table-bordered > tfoot > tr > th,
.table-bordered > thead > tr > td,
.table-bordered > tbody > tr > td,
.table-bordered > tfoot > tr > td {
  border: 1px solid #3A3A3C;
}

/* ============================================================
   DROPDOWN
   ============================================================ */

.dropdown-menu {
  background: rgba(36, 36, 38, 0.92) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 12px !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5) !important;
  padding: 6px 0;
}
.dropdown-menu > li > a {
  color: #F5F5F7;
  padding: 8px 18px;
}
.dropdown-menu > li > a:hover,
.dropdown-menu > li > a:focus,
.dropdown-menu > .active > a,
.dropdown-menu > .active > a:hover,
.dropdown-menu > .active > a:focus {
  background: rgba(10, 132, 255, 0.2) !important;
  color: #64D2FF !important;
}
.dropdown-menu .divider {
  background-color: #3A3A3C;
}

/* ============================================================
   BODY BACKGROUND
   ============================================================ */

body,
body.function-dashboard,
body[data-panel-bg] {
  background: linear-gradient(160deg, #000000 0%, #0D0D0F 40%, #121214 100%) fixed !important;
  background-color: #000000 !important;
  color: #F5F5F7;
}

/* ============================================================
   MODAL
   ============================================================ */

.modal-backdrop {
  background-color: rgba(0, 0, 0, 0.55) !important;
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
}
.modal-backdrop.in { opacity: 1 !important; }

.modal-header {
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.modal-footer {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

/* ============================================================
   ALERTS
   ============================================================ */

.alert {
  border-radius: 12px;
  border: 1px solid transparent;
}
.alert-success {
  background: rgba(48, 209, 88, 0.12);
  border-color: rgba(48, 209, 88, 0.3);
  color: #30D158;
}
.alert-info {
  background: rgba(10, 132, 255, 0.12);
  border-color: rgba(10, 132, 255, 0.3);
  color: #64D2FF;
}
.alert-warning {
  background: rgba(255, 159, 10, 0.12);
  border-color: rgba(255, 159, 10, 0.3);
  color: #FF9F0A;
}
.alert-danger {
  background: rgba(255, 69, 58, 0.12);
  border-color: rgba(255, 69, 58, 0.3);
  color: #FF453A;
}

/* ============================================================
   CARDS / DASHBOARD BOXES
   ============================================================ */

.r-box-left,
.r-box-right {
  min-height: 75px;
  border-radius: 16px !important;
  padding: 12px;
  border-width: 1px;
  border-style: solid;
  border-color: rgba(10, 132, 255, 0.35) !important;
  background: rgba(28, 28, 30, 0.7) !important;
  box-shadow:
    0 0 12px rgba(10, 132, 255, 0.12),
    0 4px 16px rgba(0, 0, 0, 0.35) !important;
}
.r-box-text > .r-box-header {
  font-size: 130%;
  color: #F5F5F7;
}
.r-box-text > .r-box-body {
  font-size: 110%;
  color: #98989D;
}

/* ============================================================
   CODE / PRE
   ============================================================ */

code {
  padding: 2px 6px;
  font-size: 90%;
  color: #FF6B8A;
  background-color: rgba(255, 69, 58, 0.12);
  border-radius: 6px;
}
kbd {
  padding: 2px 6px;
  font-size: 90%;
  color: #fff;
  background-color: #3A3A3C;
  border-radius: 6px;
  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.4);
}
pre {
  display: block;
  padding: 12px;
  margin: 0 0 10px;
  font-size: 13px;
  line-height: 1.42857143;
  color: #EBEBF5;
  background-color: #1C1C1E;
  border: 1px solid #3A3A3C;
  border-radius: 10px;
}

/* ============================================================
   MISC
   ============================================================ */

.well {
  background: rgba(28, 28, 30, 0.6) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 12px;
}

.breadcrumb {
  background: transparent;
  color: #98989D;
}
.breadcrumb > li + li:before {
  color: #636366;
}
.breadcrumb > .active {
  color: #F5F5F7;
}

.badge {
  background-color: #3A3A3C;
  color: #F5F5F7;
}
.btn-primary .badge {
  color: #0A84FF;
  background-color: #fff;
}

.label-primary { background-color: #0A84FF; }
.label-success { background-color: #30D158; }
.label-info { background-color: #5E5CE6; }
.label-warning { background-color: #FF9F0A; color: #1C1C1E; }
.label-danger { background-color: #FF453A; }

.progress {
  background-color: #2C2C2E;
  border-radius: 8px;
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.3);
}
.progress-bar {
  background-color: #0A84FF;
  box-shadow: 0 0 8px rgba(10, 132, 255, 0.4);
}

/* Cookie banner */
.r-cookie-banner {
  background: rgba(22, 22, 24, 0.9) !important;
  -webkit-backdrop-filter: blur(20px);
  backdrop-filter: blur(20px);
  border-top: 1px solid rgba(255, 255, 255, 0.08) !important;
  color: #F5F5F7 !important;
}

/* Search highlight */
.r-search-highlight {
  color: #FF453A;
  font-weight: bold;
  text-shadow: 0 0 6px rgba(255, 69, 58, 0.5);
}

/* Fallback when backdrop-filter not supported */
@supports not ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))) {
  .panel,
  .r-grid > .panel,
  .modal-content,
  .dropdown-menu,
  .navbar,
  .r-left,
  .btn-default,
  .form-control {
    background: rgba(28, 28, 30, 0.95) !important;
  }
}

/* Smooth transitions */
.panel,
.modal-content,
.dropdown-menu,
.btn,
.form-control,
.navbar {
  transition: background 0.2s ease, box-shadow 0.25s ease, border-color 0.2s ease, transform 0.2s ease;
}

/* Extra neon pulse animation for primary buttons (optional) */
@keyframes neon-pulse {
  0%, 100% {
    box-shadow:
      0 0 8px rgba(10, 132, 255, 0.5),
      0 0 20px rgba(10, 132, 255, 0.3),
      0 4px 12px rgba(0, 0, 0, 0.4),
      inset 0 1px 0 rgba(255, 255, 255, 0.25);
  }
  50% {
    box-shadow:
      0 0 12px rgba(10, 132, 255, 0.65),
      0 0 28px rgba(10, 132, 255, 0.4),
      0 4px 12px rgba(0, 0, 0, 0.4),
      inset 0 1px 0 rgba(255, 255, 255, 0.3);
  }
}
.btn-primary.neon-pulse {
  animation: neon-pulse 2.5s ease-in-out infinite;
}

